import base64

def set_line(filename, idx, b64_str):
    with open(filename, "r") as f:
        lines = f.readlines()
    lines[idx] = base64.b64decode(b64_str).decode('utf-8')
    with open(filename, "w") as f:
        f.writelines(lines)

